          pubs.add('facebook');  fb.add('feed');   break;
        case 'Facebook Stories':
          pubs.add('facebook');  fb.add('story');  break;
        case 'Facebook Reels':
          pubs.add('facebook');  fb.add('video_feeds');  break;
