// Phone Normalization Helper
function normalizeAndValidatePhone(input) {
  if (!input || typeof input !== 'string') {
    return '';
  }

  // Remove all non-digit characters
  let cleaned = input.replace(/[^0-9]/g, '');

  // Add 90 prefix if missing
  if (!cleaned.startsWith('90')) {
    if (cleaned.startsWith('0')) {
      cleaned = '9' + cleaned; // 0532 → 90532
    } else {
      cleaned = '90' + cleaned; // 532 → 90532
    }
  }

  // Validate Turkish phone format (90 + 10 digits = 12 digits)
  if (cleaned.length !== 12) {
    throw new Error(`Invalid Turkish phone number: "${input}". Expected format: +90XXXXXXXXXX (12 digits total)`);
  }

  // Validate that it starts with valid Turkish mobile prefixes
  const prefix = cleaned.substring(2, 5); // Get first 3 digits after 90
  const valid_prefixes = ['505', '506', '507', '530', '531', '532', '533', '534', '535', '536', '537', '538', '539', '540', '541', '542', '543', '544', '545', '546', '547', '548', '549', '551', '552', '553', '554', '555', '556', '557', '558', '559'];

  if (!valid_prefixes.includes(prefix)) {
    console.warn(`Phone prefix ${prefix} may not be valid Turkish mobile number`);
  }

  return 'tel:+' + cleaned;
}


/**
 * Build Final Ad Set Body (CBO)
 * Çıkış: item.json._finalBody
 * Sadece Campaign Budget kampanyalarındaki AD SET CREATE için kullanılır.
 * Bu yüzden /adsets isteğinde bütçe alanı GÖNDERMEYECEĞİZ.
 */

// ------------- Helpers -------------

const cur = item.json || {};

// curRow: varsa satır bilgisini yine tutalım (debug için)
let curRow =
  cur.row != null
    ? String(cur.row)
    : cur['Row No'] != null
    ? String(cur['Row No'])
    : undefined;

// Satır bazlı lookup için genel helper
function fromNodeByRow(nodeNames) {
  const names = Array.isArray(nodeNames) ? nodeNames : [nodeNames];

  if (curRow) {
    for (const node of names) {
      const list = $items(node, 0) || [];
      for (const it of list) {
        const j = it.json || {};
        const r =
          j.row != null
            ? String(j.row)
            : j['Row No'] != null
            ? String(j['Row No'])
            : undefined;
        if (r && r === curRow) return j;
      }
    }
  }

  for (const node of names) {
    const list = $items(node, 0) || [];
    if (list[$itemIndex]) return list[$itemIndex].json || {};
  }
  return {};
}

const clean = v =>
  typeof v === 'string'
    ? v
        .replace(/\u00A0/g, ' ')
        .replace(/\r?\n/g, ' ')
        .trim()
        .replace(/^="\s*|\s*"$/g, '')
    : v ?? '';

const toArr = v =>
  Array.isArray(v)
    ? v
    : typeof v === 'string' && v.trim()
    ? v
        .split(',')
        .map(s => s.trim())
        .filter(Boolean)
    : undefined;

const looseGet = (obj, keys) => {
  if (!obj) return undefined;
  const norm = s =>
    String(s ?? '')
      .toLowerCase()
      .replace(/\u00A0/g, ' ')
      .replace(/[^a-z0-9]/g, '')
      .trim();
  const look = Object.fromEntries(
    Object.keys(obj || {}).map(k => [norm(k), k]),
  );
  for (const k of keys) {
    const hit = look[norm(k)];
    if (hit) return obj[hit];
  }
};

const normalizeUrl = u => {
  if (typeof u !== 'string') return '';
  let s = clean(u);
  if (!s) return '';
  if (/^tel:/i.test(s)) return '';
  if (/^www\./i.test(s)) s = 'https://' + s;
  if (!/^https?:\/\//i.test(s)) s = 'https://' + s;
  try {
    return new URL(s).toString();
  } catch {
    return s;
  }
};

const normalizePhone = input => {
  if (typeof input !== 'string') return '';
  let p = clean(input);
  if (p.toLowerCase().indexOf('tel:') === 0) {
    let n = p.slice(4).replace(/[^0-9+]/g, '');
    n = n.replace(/^\++/, '+');
    if (n.charAt(0) !== '+') n = '+' + n;
    return 'tel:' + n;
  } else {
    let n2 = p.replace(/[^0-9+]/g, '').replace(/^\++/, '+');
    if (n2.charAt(0) !== '+') n2 = '+' + n2;
    return 'tel:' + n2;
  }
};

function appendUtm(base, params) {
  const entries = [];
  Object.keys(params).forEach(k => {
    const v = params[k];
    if (v != null && String(v).trim() !== '') {
      entries.push([k, v]);
    }
  });

  try {
    const url = new URL(base);
    entries.forEach(([k, v]) => url.searchParams.set(k, v));
    return url.toString();
  } catch (e) {
    if (!entries.length) return base;
    const qs = entries
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
      .join('&');
    return base + (base.indexOf('?') >= 0 ? '&' : '?') + qs;
  }
}

