const age_max           = map.age_max           ?? '';

// Budget sadece debug
const budget_type_raw    = (map.budget_type || '').toString().trim();
const daily_budgetRaw    = map.daily_budget    ?? '';
const lifetime_budgetRaw = map.lifetime_budget ?? '';

const budget_type      = budget_type_raw || 'Campaign Budget';
const isAdsetBudget    = false;
const isCampaignBudget = true;

// DESTINATION TYPE
const convCell =
  looseGet(map, [
    'conversion_location',
