// Pixel
const pixelRaw = clean(looseGet(map, ['Pixel_ID', 'Pixel ID', 'PixelId']) ?? '');
const pixel_id = String(pixelRaw).replace(/[^\d]/g, '') || undefined;
const needsPromotedObject = /OFFSITE_CONVERSIONS|LEAD/i.test(optimization_goal);
