// ------------- Helpers -------------
function clean(v) {
  if (typeof v === 'string') {
    return v
      .replace(/\u00A0/g, ' ')
      .replace(/\r?\n/g, ' ')
      .trim()
      .replace(/^="\s*|\s*"$/g, '');
  }
  return v == null ? '' : v;
}

function normalizeUrl(u) {
  if (typeof u !== 'string') return '';
  let s = clean(u);
  if (!s) return '';
  if (/^tel:/i.test(s)) return '';
  if (/^www\./i.test(s)) s = 'https://' + s;
  if (!/^https?:\/\//i.test(s)) s = 'https://' + s;
  try {
    return new URL(s).toString();
  } catch {
    return s;
  }
}

function looseGet(obj, keys) {
  if (!obj) return undefined;
  function norm(s) {
    return String(s == null ? '' : s)
      .toLowerCase()
      .replace(/\u00A0/g, ' ')
      .replace(/[^a-z0-9]/g, '')
      .trim();
  }
  const table = {};
  Object.keys(obj).forEach(k => {
    table[norm(k)] = k;
  });
  for (const cand of keys) {
    const hit = table[norm(cand)];
    if (hit) return obj[hit];
  }
  return undefined;
}

function appendUtm(base, params) {
  const entries = Object.entries(params).filter(
    ([, v]) => v != null && String(v).trim() !== '',
  );

  try {
    const url = new URL(base);
    for (const [k, v] of entries) url.searchParams.set(k, v);
    return url.toString();
  } catch {
    if (!entries.length) return base;
    const qs = entries
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
      .join('&');
    return base + (base.includes('?') ? '&' : '?') + qs;
  }
}

function normalizePhone(input) {
  if (typeof input !== 'string') return '';
  let p = clean(input);
  if (p.toLowerCase().startsWith('tel:')) {
    let n = p.slice(4).replace(/[^0-9+]/g, '');
    n = n.replace(/^\++/, '+');
    if (!n.startsWith('+')) n = '+' + n;
    return 'tel:' + n;
  } else {
    let n = p.replace(/[^0-9+]/g, '').replace(/^\++/, '+');
    if (!n.startsWith('+')) n = '+' + n;
    return 'tel:' + n;
  }
}

