//   item.json._adUpdateBody   -> sadece name + status update
//   item.json._creativeBody   -> yeni creative body (adcreatives)
//   item.json._newAdBody      -> yeni ad body (creative_id sonradan eklenecek)

const cur = item.json || {};

// ------------- Sheet / Mapping satırını bul -------------

// Mapping node: CBO dalındaki sıralama için referans
const mappingItems = $items('Mapping', 0) || [];
const row = (mappingItems[$itemIndex] || {}).json || {};

// Meta Ads Automation node: Ad Section’daki güncel değerler
const sheetItems = $items('Meta Ads Automation', 0) || [];
const sheetRow = (sheetItems[$itemIndex] || {}).json || {};

// ------------- Helpers -------------

function cleanCell(v) {
  if (typeof v !== 'string') {
    return v == null ? '' : String(v);
  }
  return v
    .replace(/\u00A0/g, ' ')
    .replace(/\r?\n/g, ' ')
    .trim()
    .replace(/^="\s*|\s*"$/g, '');
}

function normalizeUrl(u) {
  if (typeof u !== 'string') return '';
  let s = cleanCell(u);
  if (!s) return '';
  if (/^tel:/i.test(s)) return '';
  if (/^www\./i.test(s)) s = 'https://' + s;
  if (!/^https?:\/\//i.test(s)) s = 'https://' + s;
  try {
    return new URL(s).toString();
  } catch {
    return s;
  }
}

function normalizePhone(input) {
  if (typeof input !== 'string') return '';
  let p = cleanCell(input);
  if (p.toLowerCase().indexOf('tel:') === 0) {
    let n = p.slice(4).replace(/[^0-9+]/g, '');
    n = n.replace(/^\++/, '+');
    if (n.charAt(0) !== '+') n = '+' + n;
    return 'tel:' + n;
  } else {
    let n2 = p.replace(/[^0-9+]/g, '').replace(/^\++/, '+');
    if (n2.charAt(0) !== '+') n2 = '+' + n2;
    return 'tel:' + n2;
  }
}

function appendUtmRobust(baseUrl, params) {
  const entries = Object.entries(params).filter(
    ([, v]) => v != null && String(v).trim() !== '',
  );
  if (!entries.length) return baseUrl;

  try {
    const url = new URL(baseUrl);
    for (const [k, v] of entries) url.searchParams.set(k, v);
    return url.toString();
  } catch {
    const qs = entries
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
      .join('&');
    return baseUrl + (baseUrl.indexOf('?') >= 0 ? '&' : '?') + qs;
  }
}

function looseGet(obj, keys) {
  if (!obj) return undefined;
  const norm = s =>
    String(s == null ? '' : s)
      .toLowerCase()
      .replace(/\u00A0/g, ' ')
      .replace(/[^a-z0-9]/g, '')
      .trim();
  const look = {};
  Object.keys(obj).forEach(k => {
    look[norm(k)] = k;
  });
  for (const k of keys) {
    const hit = look[norm(k)];
    if (hit) return obj[hit];
  }
  return undefined;
}

// Önce dolu olanı seçmek için küçük helper
const pick = (...vals) => {
  for (const v of vals) {
