    return baseUrl + (baseUrl.indexOf('?') >= 0 ? '&' : '?') + qs;
  }
}

function looseGet(obj, keys) {
  if (!obj) return undefined;
  const norm = s =>
    String(s == null ? '' : s)
      .toLowerCase()
      .replace(/\u00A0/g, ' ')
      .replace(/[^a-z0-9]/g, '')
      .trim();
  const look = {};
  Object.keys(obj).forEach(k => {
    look[norm(k)] = k;
  });
  for (const k of keys) {
    const hit = look[norm(k)];
    if (hit) return obj[hit];
  }
  return undefined;
}

// Önce dolu olanı seçmek için küçük helper
const pick = (...vals) => {
  for (const v of vals) {
    if (v === undefined || v === null) continue;
    const s = cleanCell(v);
    if (s !== '') return s;
  }
  return '';
};

// ------------- Kaynak alanlar -------------

// ID’ler
const accountId = pick(
  looseGet(row, ['Account ID', 'account_id']),
  looseGet(sheetRow, ['Account ID', 'account_id']),
  cur.ACCOUNT_ID,
  cur.account_id,
  cur['Account ID'],
);

const adId = pick(
  looseGet(row, ['Ad ID', 'ad_id']),
  looseGet(sheetRow, ['Ad ID', 'ad_id']),
  cur.id,
  cur.ad_id,
);

const adsetId = pick(
  looseGet(row, ['Ad Set ID', 'adset_id']),
  looseGet(sheetRow, ['Ad Set ID', 'adset_id']),
  cur.adset_id,
);

// Page ID
const pageId = pick(
  looseGet(sheetRow, ['FB Page_ID', 'Page_ID', 'page_id']),
  looseGet(row, ['FB Page_ID', 'Page_ID', 'page_id']),
);

// Ad Section: metinler
const primaryText = pick(
  looseGet(sheetRow, ['Primary Text', 'primary_text', 'body']),
  looseGet(row, ['Primary Text', 'primary_text', 'body']),
  row.object_story_spec?.link_data?.message,
);

const headline = pick(
  looseGet(sheetRow, ['Headline', 'headline']),
  looseGet(row, ['Headline', 'headline']),
  row.object_story_spec?.link_data?.name,
);

const description = pick(
  looseGet(sheetRow, ['Description', 'description']),
  looseGet(row, ['Description', 'description']),
  row.object_story_spec?.link_data?.description,
);

const urlRaw = pick(
  looseGet(sheetRow, ['URL', 'url']),
  looseGet(row, ['URL', 'url']),
  row.object_story_spec?.link_data?.link,
);

const callToAct = pick(
  looseGet(sheetRow, ['Call To Action', 'call_to_action', 'cta']),
  looseGet(row, ['Call To Action', 'call_to_action', 'cta']),
  row.object_story_spec?.link_data?.call_to_action?.type,
);

const callNumber = pick(
  looseGet(sheetRow, ['Call Number', 'call_number']),
  looseGet(row, ['Call Number', 'call_number']),
  row.object_story_spec?.link_data?.call_to_action?.value?.link,
);

// Ad adı / status
const adName = pick(
  looseGet(sheetRow, ['Ad Name', 'ad_name']),
  looseGet(row, ['Ad Name', 'ad_name']),
  cur.name,
);

const adStatus = pick(
  looseGet(sheetRow, ['Ad Status', 'Status (Ad)', 'status_ad', 'ad_status']),
  looseGet(row, ['Ad Status', 'Status (Ad)', 'status_ad', 'ad_status']),
  cur.status,
);

// Platform
const platformRaw = pick(
  looseGet(sheetRow, ['Platform', 'platform']),
  looseGet(row, ['Platform', 'platform']),
);

// ------------- UTM medium -------------

let utmMedium = 'instagram';
const p = platformRaw.toLowerCase();
if (p.includes('facebook') && p.includes('instagram')) utmMedium = 'both';
else if (p.includes('facebook')) utmMedium = 'facebook';
else if (p.includes('both')) utmMedium = 'both';

// ------------- URL ve CTA -------------

const finalUrl = normalizeUrl(urlRaw);
const utmUrl = finalUrl
  ? appendUtmRobust(finalUrl, {
      utm_source: 'meta',
      utm_medium: utmMedium,
      utm_campaign: 'ads',
      utm_content: adName || 'ad',
    })
  : '';

const ctaType = (callToAct || '').toUpperCase() || 'LEARN_MORE';

let call_to_action;
if (ctaType === 'CALL_NOW') {
  call_to_action = {
    type: 'CALL_NOW',
    value: { link: normalizePhone(callNumber) || '' },
  };
} else {
  call_to_action = {
    type: ctaType,
    value: { link: utmUrl || finalUrl || '' },
  };
}

// ------------- 1) Sadece name + status update body -------------

const adUpdateBody = {};
if (adName) adUpdateBody.name = adName;
if (adStatus) adUpdateBody.status = adStatus;

if (!Object.keys(adUpdateBody).length) {
  adUpdateBody._noop = true;
}

// ------------- 2) Yeni creative body (adcreatives) -------------

const creativeBody = {
  name: adName || 'Updated Ad',
  object_story_spec: {
    page_id: pageId,
    link_data: {
      message: primaryText,
      name: headline,
      description,
      link: utmUrl || finalUrl || '',
      call_to_action,
    },
  },
};

// ------------- 3) Yeni ad body (creative_id sonradan eklenecek) -------------

const newAdBody = {
  name: adName || 'Updated Ad',
  adset_id: adsetId,
  status: adStatus || undefined,
  // creative_id HTTP node tarafında adcreative cevabından eklenecek
};

// ------------- Çıkışlar -------------

item.json._adId = adId;
item.json._accountId = accountId;
item.json._adUpdateBody = adUpdateBody;
item.json._creativeBody = creativeBody;
item.json._newAdBody = newAdBody;

return item;

parameters.jsonBody:
={
  "name": "{{$node['Build ABO Ads Update'].json._newAdBody.name}}",
  "status": "{{$node['Build ABO Ads Update'].json._newAdBody.status}}",
  "adset_id": "{{$node['Build ABO Ads Update'].json._newAdBody.adset_id}}",
  "creative": {
    "creative_id": "{{$json.id}}"
  }
}
